import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Calendar, Users, MapPin, Phone, Mail, ChevronRight, Check, PartyPopper } from "lucide-react";

const EVENT_TYPES = [
  { id: "wedding", label: "Wedding", icon: "💒" },
  { id: "reception", label: "Reception", icon: "🎊" },
  { id: "engagement", label: "Engagement", icon: "💍" },
  { id: "mehendi", label: "Mehendi/Sangeet", icon: "🌸" },
  { id: "corporate", label: "Corporate Event", icon: "🏢" },
  { id: "birthday", label: "Birthday Party", icon: "🎂" },
  { id: "festival", label: "Festival Decor", icon: "🎆" },
  { id: "anniversary", label: "Anniversary", icon: "💕" },
];

const EventPlannerCTA = () => {
  const [selectedEvents, setSelectedEvents] = useState([]);
  const [formData, setFormData] = useState({
    name: "",
    phone: "",
    email: "",
    date: "",
    venue: "",
    guests: "",
    message: "",
  });

  const toggleEvent = (id) => {
    setSelectedEvents((prev) =>
      prev.includes(id) ? prev.filter((e) => e !== id) : [...prev, id]
    );
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const eventList = selectedEvents.map((id) => EVENT_TYPES.find((e) => e.id === id)?.label).join(", ");
    const message = `*Event Planning Inquiry - D SAJAWAT*\n\n*Name:* ${formData.name}\n*Phone:* ${formData.phone}\n*Email:* ${formData.email}\n*Event Type:* ${eventList}\n*Event Date:* ${formData.date}\n*Venue:* ${formData.venue}\n*Guest Count:* ${formData.guests}\n*Requirements:* ${formData.message}`;
    window.open(`https://wa.me/919888919983?text=${encodeURIComponent(message)}`, "_blank");
  };

  return (
    <section className="relative px-6 md:px-12 lg:px-24 py-24 md:py-32" style={{ background: "linear-gradient(135deg, #1a080a 0%, #2a1015 100%)" }}>
      {/* Animated Background */}
      <div className="absolute inset-0 overflow-hidden">
        {/* Floating particles */}
        {[...Array(15)].map((_, i) => (
          <motion.div
            key={i}
            className="absolute w-1 h-1 rounded-full"
            style={{
              background: "#d4af37",
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
            }}
            animate={{
              y: [0, -50, 0],
              opacity: [0.2, 0.6, 0.2],
            }}
            transition={{
              duration: 3 + Math.random() * 2,
              repeat: Infinity,
              delay: Math.random() * 2,
            }}
          />
        ))}
      </div>

      <div className="max-w-6xl mx-auto relative">
        {/* Header */}
        <motion.div
          className="text-center mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.7 }}
        >
          <motion.div
            className="inline-flex items-center gap-2 px-4 py-2 rounded-full mb-6"
            style={{ background: "rgba(212,175,55,0.15)", border: "1px solid rgba(212,175,55,0.3)" }}
            animate={{ scale: [1, 1.02, 1] }}
            transition={{ duration: 2, repeat: Infinity }}
          >
            <PartyPopper size={16} color="#d4af37" />
            <span className="text-xs tracking-[0.2em] uppercase" style={{ color: "#d4af37" }}>For Event Planners & Organizers</span>
          </motion.div>

          <h2 className="serif mb-4" style={{ fontSize: "clamp(36px, 5vw, 56px)", fontWeight: 400, color: "#ffffff" }}>
            Plan Your <span style={{ color: "#d4af37", fontStyle: "italic" }}>Dream Event</span>
          </h2>
          <p className="max-w-2xl mx-auto" style={{ color: "rgba(255,255,255,0.7)", lineHeight: 1.7 }}>
            From intimate gatherings to grand celebrations, we provide premium fabrics and expert consultation for every occasion.
          </p>
        </motion.div>

        {/* Main Content */}
        <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
          {/* Left Side - Event Types */}
          <motion.div
            className="lg:col-span-2"
            initial={{ opacity: 0, x: -30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6 }}
          >
            <h3 className="text-lg font-semibold mb-6" style={{ color: "#d4af37" }}>
              Select Your Event Type
            </h3>
            <div className="grid grid-cols-2 gap-3">
              {EVENT_TYPES.map((event, i) => (
                <motion.button
                  key={event.id}
                  className={`p-4 rounded-xl text-left transition-all ${selectedEvents.includes(event.id) ? 'ring-2 ring-[#d4af37]' : ''}`}
                  style={{
                    background: selectedEvents.includes(event.id)
                      ? "linear-gradient(135deg, rgba(212,175,55,0.3), rgba(212,175,55,0.1))"
                      : "rgba(255,255,255,0.05)",
                    border: selectedEvents.includes(event.id)
                      ? "1px solid #d4af37"
                      : "1px solid rgba(255,255,255,0.1)",
                  }}
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ delay: i * 0.05 }}
                  whileHover={{ scale: 1.02, background: "rgba(212,175,55,0.1)" }}
                  onClick={() => toggleEvent(event.id)}
                >
                  <div className="text-2xl mb-2">{event.icon}</div>
                  <div className="text-sm font-medium" style={{ color: selectedEvents.includes(event.id) ? "#d4af37" : "#ffffff" }}>
                    {event.label}
                  </div>
                  {selectedEvents.includes(event.id) && (
                    <motion.div
                      className="absolute top-2 right-2"
                      initial={{ scale: 0 }}
                      animate={{ scale: 1 }}
                    >
                      <Check size={14} color="#d4af37" />
                    </motion.div>
                  )}
                </motion.button>
              ))}
            </div>

            {/* Quick Stats */}
            <div className="mt-8 grid grid-cols-2 gap-4">
              {[
                { value: "500+", label: "Events Yearly" },
                { value: "12+", label: "Years Experience" },
              ].map((stat, i) => (
                <motion.div
                  key={stat.label}
                  className="p-4 rounded-xl text-center"
                  style={{ background: "rgba(212,175,55,0.1)", border: "1px solid rgba(212,175,55,0.2)" }}
                  initial={{ opacity: 0, scale: 0.8 }}
                  whileInView={{ opacity: 1, scale: 1 }}
                  viewport={{ once: true }}
                  transition={{ delay: 0.3 + i * 0.1 }}
                  whileHover={{ scale: 1.05 }}
                >
                  <div className="text-2xl font-bold" style={{ color: "#d4af37" }}>{stat.value}</div>
                  <div className="text-xs uppercase tracking-wider mt-1" style={{ color: "rgba(255,255,255,0.6)" }}>{stat.label}</div>
                </motion.div>
              ))}
            </div>
          </motion.div>

          {/* Right Side - Form */}
          <motion.div
            className="lg:col-span-3"
            initial={{ opacity: 0, x: 30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6, delay: 0.2 }}
          >
            <div className="p-8 rounded-2xl" style={{ background: "rgba(255,255,255,0.05)", border: "1px solid rgba(212,175,55,0.2)", backdropFilter: "blur(10px)" }}>
              <h3 className="serif text-2xl mb-6" style={{ color: "#ffffff" }}>Get a Custom Quote</h3>

              <form onSubmit={handleSubmit} className="space-y-5">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                  <div>
                    <label className="block text-xs uppercase tracking-wider mb-2" style={{ color: "rgba(255,255,255,0.6)" }}>Your Name *</label>
                    <div className="relative">
                      <Users size={16} className="absolute left-4 top-1/2 -translate-y-1/2" style={{ color: "#d4af37" }} />
                      <input
                        type="text"
                        required
                        className="w-full pl-11 pr-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white placeholder-white/40 focus:border-[#d4af37] focus:outline-none transition-colors"
                        placeholder="Enter your name"
                        value={formData.name}
                        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs uppercase tracking-wider mb-2" style={{ color: "rgba(255,255,255,0.6)" }}>Phone *</label>
                    <div className="relative">
                      <Phone size={16} className="absolute left-4 top-1/2 -translate-y-1/2" style={{ color: "#d4af37" }} />
                      <input
                        type="tel"
                        required
                        className="w-full pl-11 pr-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white placeholder-white/40 focus:border-[#d4af37] focus:outline-none transition-colors"
                        placeholder="Your phone number"
                        value={formData.phone}
                        onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                      />
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                  <div>
                    <label className="block text-xs uppercase tracking-wider mb-2" style={{ color: "rgba(255,255,255,0.6)" }}>Event Date</label>
                    <div className="relative">
                      <Calendar size={16} className="absolute left-4 top-1/2 -translate-y-1/2" style={{ color: "#d4af37" }} />
                      <input
                        type="date"
                        className="w-full pl-11 pr-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white focus:border-[#d4af37] focus:outline-none transition-colors [&::-webkit-calendar-picker-indicator]:invert"
                        value={formData.date}
                        onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs uppercase tracking-wider mb-2" style={{ color: "rgba(255,255,255,0.6)" }}>Guest Count</label>
                    <div className="relative">
                      <Users size={16} className="absolute left-4 top-1/2 -translate-y-1/2" style={{ color: "#d4af37" }} />
                      <select
                        className="w-full pl-11 pr-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white focus:border-[#d4af37] focus:outline-none transition-colors"
                        value={formData.guests}
                        onChange={(e) => setFormData({ ...formData, guests: e.target.value })}
                      >
                        <option value="" className="text-black">Select guest count</option>
                        <option value="50-100" className="text-black">50-100</option>
                        <option value="100-300" className="text-black">100-300</option>
                        <option value="300-500" className="text-black">300-500</option>
                        <option value="500-1000" className="text-black">500-1000</option>
                        <option value="1000+" className="text-black">1000+</option>
                      </select>
                    </div>
                  </div>
                </div>

                <div>
                  <label className="block text-xs uppercase tracking-wider mb-2" style={{ color: "rgba(255,255,255,0.6)" }}>Venue / Location</label>
                  <div className="relative">
                    <MapPin size={16} className="absolute left-4 top-1/2 -translate-y-1/2" style={{ color: "#d4af37" }} />
                    <input
                      type="text"
                      className="w-full pl-11 pr-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white placeholder-white/40 focus:border-[#d4af37] focus:outline-none transition-colors"
                      placeholder="City, venue name, or area"
                      value={formData.venue}
                      onChange={(e) => setFormData({ ...formData, venue: e.target.value })}
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-xs uppercase tracking-wider mb-2" style={{ color: "rgba(255,255,255,0.6)" }}>Your Requirements</label>
                  <textarea
                    rows={4}
                    className="w-full px-4 py-3 rounded-xl bg-white/5 border border-white/10 text-white placeholder-white/40 focus:border-[#d4af37] focus:outline-none transition-colors resize-none"
                    placeholder="Tell us about your event vision, fabric preferences, or any specific requirements..."
                    value={formData.message}
                    onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                  />
                </div>

                <motion.button
                  type="submit"
                  className="w-full py-4 rounded-xl font-semibold flex items-center justify-center gap-3"
                  style={{ background: "linear-gradient(135deg, #d4af37, #f4d77a)", color: "#1a080a" }}
                  whileHover={{ scale: 1.02, boxShadow: "0 8px 30px rgba(212,175,55,0.4)" }}
                  whileTap={{ scale: 0.98 }}
                >
                  <Phone size={18} />
                  Get Free Consultation on WhatsApp
                  <ChevronRight size={18} />
                </motion.button>
              </form>
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  );
};

export default EventPlannerCTA;
